usage:
import { AiComposerMinimal } from "@/components/design-for-ai/ai-composer-minimal";

<AiComposerMinimal
  placeholder="Ask anything…"
  files={[{ id: "roadmap", name: "q3-launch-roadmap.md", detail: "Edited today" }]}
  onSubmit={async (message) => { await ask(message); }} // return a promise to keep it generating
  onStop={() => abort()}
/>

// Controlled: you own the state
const [state, setState] = useState<AiComposerState>("idle");
<AiComposerMinimal state={state} onStateChange={setState} onSubmit={(m) => send(m)} />
